#!/bin/sh
# Build a .deb around an already built static binary.
#
#   scripts/build-deb.sh BINARY ARCH OUTPUT.deb
#   ARCH is the Debian architecture: amd64 or arm64.
#
# The binary is statically linked (musl), so the package has no libc
# dependency and installs on every Debian/Ubuntu release that has git and
# OpenSSH. Man page and completions are generated by the host-runnable binary
# named in GEN_BIN (defaults to BINARY).
set -eu
cd "$(dirname "$0")/.."

BIN=${1:?usage: build-deb.sh BINARY ARCH OUTPUT.deb}
ARCH=${2:?missing ARCH (amd64|arm64)}
OUT=${3:?missing OUTPUT.deb}
GEN_BIN=${GEN_BIN:-$BIN}

case "$ARCH" in amd64|arm64) ;; *) echo "unsupported ARCH $ARCH" >&2; exit 1 ;; esac
VERSION=$(sed -n 's/^version = "\(.*\)"$/\1/p' Cargo.toml | head -n1)

ROOT=$(mktemp -d)
trap 'rm -rf "$ROOT"' EXIT
P="$ROOT/pkg"
install -d -m 0755 "$P/DEBIAN" "$P/usr/bin" "$P/usr/share/man/man1" \
    "$P/usr/share/bash-completion/completions" "$P/usr/share/zsh/vendor-completions" \
    "$P/usr/share/fish/vendor_completions.d" "$P/usr/share/doc/ndo4git"

install -m 0755 "$BIN" "$P/usr/bin/ndo4git"
ln -s ndo4git "$P/usr/bin/git-ndo4git"
"$GEN_BIN" man | gzip -9n > "$P/usr/share/man/man1/ndo4git.1.gz"
"$GEN_BIN" completions bash > "$P/usr/share/bash-completion/completions/ndo4git"
"$GEN_BIN" completions zsh > "$P/usr/share/zsh/vendor-completions/_ndo4git"
"$GEN_BIN" completions fish > "$P/usr/share/fish/vendor_completions.d/ndo4git.fish"
chmod 0644 "$P"/usr/share/man/man1/* "$P"/usr/share/bash-completion/completions/* \
    "$P"/usr/share/zsh/vendor-completions/* "$P"/usr/share/fish/vendor_completions.d/*

cat > "$P/usr/share/doc/ndo4git/copyright" <<COPY
Format: https://www.debian.org/doc/packaging-manuals/copyright-format/1.0/
Upstream-Name: ndo4git
Source: https://github.com/NDO4ME/NDO4Git

Files: *
Copyright: NDO4ME
License: MIT
$(sed -e 's/^$/./' -e 's/^/ /' LICENSE)
COPY
gzip -9n -c README.md > "$P/usr/share/doc/ndo4git/README.md.gz"
chmod 0644 "$P"/usr/share/doc/ndo4git/*

install -m 0755 packaging/deb/postinst "$P/DEBIAN/postinst"
install -m 0755 packaging/deb/prerm "$P/DEBIAN/prerm"

SIZE=$(du -sk "$P" | cut -f1)
cat > "$P/DEBIAN/control" <<CTL
Package: ndo4git
Version: $VERSION
Section: vcs
Priority: optional
Architecture: $ARCH
Maintainer: NDO4ME <git@ndo4.me>
Installed-Size: $SIZE
Depends: git, openssh-client
Homepage: https://github.com/NDO4ME/NDO4Git
Description: transparent per-repository SSH keys for git
 ndo4git picks a dedicated SSH key per repository whenever git talks to
 GitHub, Codeberg (Forgejo) or GitLab over SSH. Keys are generated locally,
 stored encrypted in SQLite and handed to ssh through core.sshCommand, so
 git push/pull/fetch/clone work unchanged.
 .
 The binary is statically linked and has no library dependencies.
CTL

(cd "$P" && find usr -type f -print0 | sort -z | xargs -0 md5sum > DEBIAN/md5sums)
find "$P" -exec touch -h -d "@${SOURCE_DATE_EPOCH:-0}" {} +
dpkg-deb --root-owner-group -Zxz --build "$P" "$OUT" >/dev/null
echo "built $OUT"
